// ─── File: GcRootsDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.gcroots;

import java.lang.ref.WeakReference;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class GcRootsDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // CASE 1: a reference CYCLE with NO root reaching it → collected (NOT a leak).
        WeakReference<Transaction> probe = createUnreachableCycle();
        System.gc();                 // request a collection
        Thread.sleep(200);
        boolean collected = probe.get() == null;
        log.info(() -> "cycle (txn <-> reversal) collected after dropping roots? " + collected
                + "  → circular refs are NOT a leak (reachability, not ref-counting)");

        // CASE 2: a STATIC registry is a GC ROOT → retained forever = REAL leak.
        for (int i = 0; i < 1000; i++) {
            TransactionRegistry.keep(new Transaction("TXN-" + i, 1000)); // static holds them
        }
        System.gc();
        Thread.sleep(200);
        log.warning(() -> "static registry still retains " + TransactionRegistry.size()
                + " transactions → reachable from a GC ROOT → genuine leak until cleared");

        // Fix: break the root reference.
        TransactionRegistry.clear();
        log.info(() -> "after clearing the static root, retained = " + TransactionRegistry.size());
    }

    // Build a cycle, then let the only local references go out of scope on return.
    private static WeakReference<Transaction> createUnreachableCycle() {
        Transaction txn = new Transaction("TXN-CYCLE", 5000);
        Reversal rev = new Reversal("REV-CYCLE");
        txn.setReversal(rev);   // txn → rev
        rev.setTransaction(txn); // rev → txn  (CYCLE)
        // Return only a WEAK reference; the strong locals die when this method returns,
        // so NO GC root reaches either object despite the cycle between them.
        return new WeakReference<>(txn);
    }
}

// ─── Would be in Transaction.java (half of the cycle) ───
class Transaction {
    private final String id;
    private final long amountPaise;
    private Reversal reversal; // strong ref forming part of the cycle
    Transaction(String id, long amountPaise) { this.id = id; this.amountPaise = amountPaise; }
    void setReversal(Reversal r) { this.reversal = r; }
    String getId() { return id; }
}

// ─── Would be in Reversal.java (other half of the cycle) ───
class Reversal {
    private final String id;
    private Transaction transaction; // strong ref back → completes the cycle
    Reversal(String id) { this.id = id; }
    void setTransaction(Transaction t) { this.transaction = t; }
    String getId() { return id; }
}

// ─── Would be in TransactionRegistry.java (STATIC field = GC ROOT = real leak) ───
class TransactionRegistry {
    // static → a GC root. Everything here stays reachable → never collected.
    private static final java.util.List<Transaction> KEPT = new java.util.ArrayList<>();
    static void keep(Transaction t) { KEPT.add(t); } // retains forever (the leak)
    static int size() { return KEPT.size(); }
    static void clear() { KEPT.clear(); }            // the fix: break the root reference
}
